{"repository_full_name":"BestNameYet/StateMachines","path":"ChatMachines/Workflow Interactive Procedures/AGENTS Procedure/issue-run-triggers/trigger.template.schema.json","sha":"ae3e244ca36a69f22c29a13ccfaf6fed8bf25021","content":"{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/BestNameYet/StateMachines/blob/main/ChatMachines/Workflow%20Interactive%20Procedures/AGENTS%20Procedure/issue-run-triggers/trigger.template.schema.json",
  "title": "AGENTS Procedure issue-run trigger",
  "description": "Agent-submitted trigger files contain only startProcedure and nonce. After initialization, the workflow marks the trigger consumed and writes issue metadata and an initial JSON receipt snapshot.",
  "type": "object",
  "required": ["startProcedure", "nonce"],
  "properties": {
    "startProcedure": {
      "type": "boolean",
      "description": "Set true in a new trigger file. The workflow changes it to false after binding and initializing the issue."
    },
    "nonce": {
      "type": "integer",
      "minimum": 0,
      "description": "Non-negative integer that must match the numeric suffix in the trigger filename."
    },
    "procedureName": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9_-]*$",
      "description": "Written by the workflow from the filename prefix."
    },
    "procedureIdentifier": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9_-]*[0-9]+$",
      "description": "The filename stem, such as buildProcedure12."
    },
    "procedureIssueNumber": {
      "type": "integer",
      "minimum": 1,
      "description": "GitHub issue number created for this trigger."
    },
    "procedureIssueUrl": {
      "type": "string",
      "format": "uri",
      "description": "URL of the issue bound to this trigger."
    },
    "procedureTitle": {
      "type": "string",
      "description": "Canonical title applied by the issue runner after issue creation."
    },
    "procedureReceiptPath": {
      "type": "string",
      "description": "Path to the canonical mutable JSON run receipt under issue-runs/."
    },
    "procedureSavedHere": {
      "$ref": "#/$defs/procedureReceipt",
      "description": "Snapshot of the initialized receipt when the trigger is consumed. The issue-runs file remains live."
    },
    "procedureReceipts": {
      "type": "array",
      "items": { "$ref": "#/$defs/procedureReceipt" },
      "description": "Ordered receipt snapshots, beginning with the initialized receipt and appended after later issue workflow updates."
    }
  },
  "$defs": {
    "procedureReceipt": {
      "type": "object",
      "required": ["state", "done", "request", "lastCommentId", "newFiles", "history", "toolInvocations"],
      "properties": {
        "state": { "type": "object" },
        "done": { "type": "boolean" },
        "request": { "type": "integer", "minimum": 1 },
        "lastCommentId": { "type": "integer", "minimum": 0 },
        "newFiles": { "type": "array", "items": { "type": "string" } },
        "history": { "type": "array", "items": { "type": "object" } },
        "toolInvocations": { "type": "array", "items": { "type": "object" } },
        "triggerIdentifier": { "type": "string" }
      },
      "additionalProperties": false
    }
  },
  "allOf": [
    {
      "if": { "properties": { "startProcedure": { "const": true } }, "required": ["startProcedure"] },
      "then": { "maxProperties": 2 }
    },
    {
      "if": { "properties": { "startProcedure": { "const": false } }, "required": ["startProcedure"] },
      "then": {
        "required": ["procedureName", "procedureIdentifier", "procedureIssueNumber", "procedureIssueUrl", "procedureTitle", "procedureReceiptPath", "procedureSavedHere"]
      }
    }
  ],
  "additionalProperties": false
}
","message":"Allow appended receipt snapshots in trigger JSON"}

